mapper.update:
UPDATE forum_post
SET title = #{title},
    content = #{content},
    category_id = #{categoryId}
WHERE id = #{id}

mapper.select:
SELECT FROM forum_post f LEFT JOIN forum_category fc ON fc.id = f.category_id
MATCH(f.title, f.content) AGAINST (#{keyword} IN BOOLEAN MODE)
(f.title LIKE CONCAT('%', #{keyword}, '%') OR f.content LIKE CONCAT('%', #{keyword}, '%'))
AND f.category_id = #{categoryId}
ORDER BY f.pinned DESC, COALESCE(f.last_reply_time, f.created_time) DESC, f.id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE forum_post
SET reply_count = #{replyCount},
    last_reply_time = #{lastReplyTime}
WHERE id = #{id}

mapper.select:
SELECT id, post_id, title, content, category_id, edited_by, created_time,
       DATE_FORMAT(created_time, '%Y-%m-%d %H:%i') AS created_time_text
FROM forum_post_history
WHERE post_id = #{postId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, name, sort_order, enabled, created_time
FROM forum_category
WHERE id = #{id}

SELECT id, post_id, content, author_user, author_name, created_time,
       DATE_FORMAT(created_time, '%Y-%m-%d %H:%i') AS created_time_text
FROM forum_reply
WHERE post_id = #{postId}
ORDER BY id ASC
LIMIT #{limit}
